-- ─── Data migration (hand-written) ──────────────────────────────────────────
-- Every organisation gets a "General" project (key GEN) that receives its existing tasks.
-- Task numbers follow creation order; kanban positions follow the same order.
INSERT INTO "Project" ("id", "organizationId", "key", "name", "description", "updatedAt")
SELECT 'prj_' || o."id", o."id", 'GEN', 'General', 'Tasks created before projects existed', CURRENT_TIMESTAMP
FROM "Organization" o;

UPDATE "Task" t SET "projectId" = 'prj_' || t."organizationId";

UPDATE "Task" t SET "number" = n.rn, "position" = n.rn * 1024
FROM (SELECT "id", ROW_NUMBER() OVER (PARTITION BY "projectId" ORDER BY "createdAt", "id") AS rn FROM "Task") n
WHERE n."id" = t."id";

UPDATE "Project" p SET "taskCounter" = COALESCE((SELECT MAX("number") FROM "Task" t WHERE t."projectId" = p."id"), 0);

-- Finished tasks get a completion time so history and analytics are consistent
UPDATE "Task" SET "completedAt" = "updatedAt" WHERE "status" = 'DONE' AND "completedAt" IS NULL;

ALTER TABLE "Task" ALTER COLUMN "number" SET NOT NULL;
ALTER TABLE "Task" ALTER COLUMN "projectId" SET NOT NULL;

